   258→    public void dasdasd(List<int> AreaIds, out float x1, out float x2, out float y1, out float y2)
   259→    {
   260→        x1 = float.MinValue;
   261→        y1 = float.MinValue;
   262→        x2 = float.MinValue;
   263→        y2 = float.MinValue;
   264→
   265→        for (int i = 0; i < AreaIds.Count; i++)
   266→        {
   267→            areaId = AreaIds[i];
   268→            Vector2 top = FreeBuildScene.convertToViewPosByTilePos(AreaLockController.getInstance().getPosFromArea(areaId));
   269→            Vector2 bottom = FreeBuildScene.convertToViewPosByTilePos(AreaLockController.getInstance().getPosFromArea(areaId) + new Vector2(7, 7));
   270→            Vector2 left = FreeBuildScene.convertToViewPosByTilePos(AreaLockController.getInstance().getPosFromArea(areaId) + new Vector2(0, 7));
   271→            Vector2 right = FreeBuildScene.convertToViewPosByTilePos(AreaLockController.getInstance().getPosFromArea(areaId) + new Vector2(7, 0));
   272→
   273→            Vector2 topRightVec = CCDirector.getInstance().getWinSize() - new Vector2(right.x, top.y) - topRightOffset;
   274→            Vector2 bottomLeftVec = -new Vector2(left.x, bottom.y) + bottomLeftOffset;
   275→
   276→            var currentPos = CCDirector.getInstance().getWinSize() / 2 - AreaLockController.getInstance().getViewPosFromArea(areaId);
   277→            var worldBound = FreeBuildScene.getInstance().getHFViewport().WorldBound;
   278→
   279→            float x = ((-topRightVec.x + CCDirector.getInstance().getWinSize().x - worldBound.origin.x) / worldBound.size.x - 0.5f) * 2f;
   280→            float y = ((-topRightVec.y + CCDirector.getInstance().getWinSize().y - worldBound.origin.y) / worldBound.size.y - 0.5f) * 2f;
   281→
   282→            x1 = Mathf.Max(x1, x);
   283→            y1 = Mathf.Max(y1, y);
   284→
   285→            x = ((bottomLeftVec.x + worldBound.origin.x) / worldBound.size.x + 0.5f) * 2f;
   286→            y = ((bottomLeftVec.y + worldBound.origin.y) / worldBound.size.y + 0.5f) * 2f;
   287→
   288→            x2 = Mathf.Max(x2, x);
   289→            y2 = Mathf.Max(y2, y);
   290→        }
   291→
   292→        x1 = Mathf.CeilToInt(x1 * 100) / 100f;
   293→        x2 = Mathf.CeilToInt(x2 * 100) / 100f;
   294→        y1 = Mathf.CeilToInt(y1 * 100) / 100f;
   295→        y2 = Mathf.CeilToInt(y2 * 100) / 100f;
   296→    }
