   418→    /// <summary>
   419→    /// 初始化本地资源
   420→    /// </summary>
   421→    /// <returns></returns>
   422→    private IEnumerator LocalBundlesInit(bool updateModel, Action callback)
   423→    {
   424→        yield return 1;
   425→        assetBundleInit = new AssetBundleInit();
   426→        InitSpecialChannel();
   427→        bool isSuccess = assetBundleInit.LocalResInit(LocalTextController.shared().GetLanguage().ToString(), () =>
   428→        {
   429→            //初始话完本地资源后，就可以加载ArchivedData文件了，这里根据ArchivedData配置重新设置下语言
   430→            LocalTextController.shared().setLang(ArchivedData.Instance.Language, ArchivedData.Instance.UIBranch);
   431→            InitSpecialChannel();
   432→            return LocalTextController.shared().GetLanguage().ToString();
   433→        });
   434→
   435→        if (!isSuccess)
   436→        {
   437→            LogCommon.LogError("本地资源初始化失败，请检查");
   438→            yield break;
   439→        }
   440→
   441→        //创建loading界面
   442→        ResInitLoadingViewController.CreatResInitLoadingView();
   443→
   444→        this.UnitySetting();
   445→        SpriteAtlasManager.atlasRequested += SpriteAtlasManager_atlasRequested;
   446→
   447→
   448→        if (!updateModel)
   449→        {
   450→            GetPlayerLoginInfo();
   451→        }
   452→
   453→        if (callback != null)
   454→        {
   455→            callback.Invoke();
   456→        }
   457→    }
